with with_prev as (select *, lag(reading_ts) over (partition by device_code order by reading_ts, id) as prev_reading_ts from device_readings), with_gaps as (select *, case when prev_reading_ts is null or reading_ts > prev_reading_ts + interval 20 minutes then 1 else 0 end as new_group_flag from with_prev), sessions_device_readings as (select *, sum(new_group_flag) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as island_id from with_gaps) select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, new_group_flag, case when device_code rlike '^(DV-01|DV-03)$' then 'PRIORITY' else 'OTHER_ZONE' end as device_code_zone from sessions_device_readings order by id desc
